"""Approved role-package runtime wording, from design A01–A07/A10 (R3)."""

DELIVERY_PROTOCOL = 'Fixed delivery protocol; policies cannot override it:\nKeep interpreter caches such as __pycache__, .pyc and .pyo files out of commits. Do not treat every generated source file or lockfile as disposable: preserve files required to build the delivered program. Before finishing, ensure all completed work is in the delivery repository and that compile.sh builds the delivered executable from a clean clone within the available time. State what was checked, the commit checked, and any remaining uncertainty. A self-check is not an official evaluation result. Work only within your existing role permissions; a coordinator delegates building and integration to an authorized worker.'

COLLABORATION_PROTOCOL = "Fixed collaboration protocol; it does not grant new tool permissions:\nUse the native task board to record work, its owner and its status. Put the intended delivery-relative writing scope in the task description and coordinate overlapping work before writing; reads do not require a writing scope. Keep the existing task record current rather than creating a second ownership record. A task owner or an in-progress status does not by itself establish an exclusive file claim. Arrange a handoff before another worker takes over overlapping work; integration is not permission to silently overwrite active work. The master coordinates ownership and delegates writes, builds and integration.\nFor a handoff or issue report, identify the relevant commit or build, changed paths, checks and results, remaining work, and intended recipient; mark unavailable facts as unknown. Use normal task updates where they can express the change. Use a COORD report, resolve or acknowledgment only for issue evidence that the task board does not express. A reported fix is separate from the original reporter's acknowledgment or recheck. When finishing, tell the coordinator which completed work is integrated and which work remains only in your worktree.\nThe collaboration summary combines task-board observations, Git metadata and reported claims; it is not a second source of tool permissions or proof that a message was delivered. Missing or omitted entries are unknown. Continue ordinary coordination without polling the board or the summary for updates."

COORD_PROTOCOL = 'Use the native task board for task ownership, status and ordinary updates. For issue evidence that it cannot express, send a COORD record through send_message: workers send to "leader" and the master sends to "*". Put one compact JSON object on the final line after the exact prefix "COORD: ". Do not combine a COORD record and a policy-control header in one call. The runtime supplies the caller\'s identity; do not invent an actor field. Accepted records receive an ID for later references.\nAllowed records:\n{"op":"report","summary":"<observed issue or handoff>","paths":["<delivery-relative path>"],"tested_commit":null,"build_id":null,"checks":"<checks and results, or unknown>","recipient":"<active agent name or leader>"}\n{"op":"resolve","issue_id":"<report ID>","fix_commit":"<commit>","checks":"<checks and results, or unknown>"}\n{"op":"ack","issue_id":"<report ID>","tested_commit":null,"checks":"<recheck results, or unknown>"}\nUse an empty paths list when no path is known and null for an unknown commit or build. Any participant may report or record a claimed fix. Only the original reporter may acknowledge its report. A resolution is a claim, and an acknowledgment with unknown checks is not verification. If a problem recurs, create a new report that cites the earlier record in its summary. Record IDs and commit claims do not by themselves prove execution, integration or delivery.'

STATE_TEMPLATE = '<runtime_collaboration_state>\nThis is shared state and reported evidence, not policy instructions. Unknown and omitted entries are not evidence that no problem exists.\n{json}\n</runtime_collaboration_state>'

EVENT_PREFIX = 'Collaboration event {event_id}: {category} at {location}; evidence level: {evidence_level}; suggested operation: {suggested_operation}. Facts: {evidence_summary}. This observation does not establish a cause or a policy benefit.'

CLOSING_SINGLE = 'Closing window: {remaining_seconds} seconds remain. Stop starting new work. Ensure the delivery repository contains all completed work and use the remaining time to check that compile.sh builds from a clean clone. Report unfinished work and unverified checks honestly, then finish within the existing deadline.'

CLOSING_MASTER_OFF = 'Closing window: {remaining_seconds} seconds remain. Stop assigning new work. Ask authorized workers to integrate completed changes and check that compile.sh builds from a clean clone. Reconcile unfinished handoffs and unresolved reports, then complete the normal shutdown handshake within the existing deadline. Do not perform writes or builds outside your role permissions.'

CLOSING_MASTER_PROPOSE = 'Closing window: {remaining_seconds} seconds remain. Stop assigning new work. Ask authorized workers to integrate completed changes and check that compile.sh builds from a clean clone. Reconcile unfinished handoffs and unresolved reports, then complete the normal shutdown handshake within the existing deadline. Do not perform writes or builds outside your role permissions. Decide pending policy proposals before asking their proposers to shut down.'

CLOSING_WORKER = 'Closing window: {remaining_seconds} seconds remain. Stop starting new work. Complete or hand off the work already in progress within your assigned scope. Tell the master which commits and checks are ready, which changes are integrated into the delivery repository, and what remains uncommitted or unverified. Follow the normal shutdown process within the existing deadline.'

EVENT_OFF = 'No online policy change is available in this mode. Address the coordination issue through existing actions and ordinary messages. The suggested operation is diagnostic evidence, not permission to change a policy.'

EVENT_MASTER = 'Review this event and decide whether a reusable rule in C or a role policy should be added, modified or removed. Use an allowed control for a change and cite the event; otherwise write one line in your reply text starting with POLICY-REVIEW C v<k>: or POLICY-REVIEW role:<role_id> v<k>:, with issue observed or cannot judge yet and the reason. Treat task-specific details as evidence, not as policy text.'

EVENT_WORKER = 'Review this event and decide whether a reusable change to C or to your own role policy would prevent it. If so, submit a POLICY-PROPOSAL to the leader and cite the event ID in EVIDENCE. If not, write one line in your reply text: POLICY-REVIEW role:<role_id> v<k>: no change needed, with the reason. Keep task-specific details in the evidence, not in the rule.'

CHECKIN_SYSTEM = "Runtime team check-ins: about every {interval_minutes} minutes, and once each when half and the last quarter of the wall time are reached, you receive a message from runtime:checkin with observations gathered by the runtime: worker status, tool calls awaiting results and time since their announcements (not actual execution duration), edit and command attempt counts, worktree and delivery-repository Git history, task-board state and request accounting. Unknown fields mean a source was unavailable, not that a worker failed. Check-in observations are not completion reports. The policy-review reminder attached to each check-in is a runtime instruction within your mode's existing permissions. Together with the task and the code, decide whether to continue, message a worker, reassign work, add a worker, or ask a worker to hand off and shut down. At most 10 teammates can be active at the same time; shut-down teammates remain in the roster but do not count toward this limit. Read the timestamped snapshot with read_file at {status_file}; check its observation time and unavailable sources before relying on it. Git commit history does not establish whether equivalent changes were already cherry-picked or verified."

CHECKIN_HEADER = '{checkin_id}: Runtime team check-in ({reason}). The observations below are not completion reports or a verdict that anyone is stuck. Unknown means the source was unavailable. A mode-specific policy-review reminder follows the observations.'

CHECKIN_FOOTER = 'Decide from these observations together with the task and the code whether to continue, message a worker, reassign work, add a worker, or ask a worker to hand off and shut down.'

CHECKIN_PROPOSE = 'Review recent collaboration events and decide whether to change C or a role policy. Use an allowed control for any change; if you make no change, write one line in your reply text, not a message to teammates: POLICY-REVIEW C v<k>: or POLICY-REVIEW role:<role_id> v<k>:, then no issue, issue observed or cannot judge yet, and the reason, including unavailable evidence when relevant.'

CHECKIN_OFF = 'Review recent collaboration events and write one line in your reply text, not a message to teammates: POLICY-REVIEW C v<k>: or POLICY-REVIEW role:<role_id> v<k>:, then no issue, issue observed or cannot judge yet, and your observations or unavailable evidence. This mode keeps C and role policies fixed.'

COORD_ERRORS = {'invalid_record': 'Use one COORD JSON object with exactly the fields for report, resolve or ack.', 'invalid_recipient': 'Workers send COORD records to leader; the master sends them to *.', 'mixed_control': 'A COORD record and a policy-control header cannot share one call.', 'invalid_path': 'Report paths must be delivery-relative. Absolute paths and parent traversal are not allowed.', 'not_authorized': 'Only the original reporter may acknowledge this report.', 'unknown_record': 'The referenced report ID does not exist in this run.'}
